<?php declare(strict_types=1);$fmt=static fn($v)=>$v===null?'—':number_format((float)$v,2,',','.').'e';?><section class="page-intro"><div><span class="kicker">MARKTANALYSE</span><h1>Market Intelligence</h1><p>Samengevatte koop- en verkoopprijzen met confidence- en dealscore.</p></div><div class="actions"><a class="btn" href="/admin/intelligence-refresh">Herberekenen</a></div></section><section class="surface"><form class="searchbar" method="get"><input name="q" value="<?=h($query)?>" placeholder="Zoek item of markt"><button class="btn">Zoeken</button></form></section><section class="surface"><div class="tablewrap"><table><thead><tr><th>Item</th><th>Beste WTB</th><th>Beste WTS</th><th>Mediaan</th><th>Confidence</th><th>Deal</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><a class="itemlink" href="/market?key=<?=rawurlencode((string)$r['market_key'])?>"><?=h($r['item']??$r['market_key'])?></a><small class="muted" style="display:block"><?=h($r['market_key'])?></small></td><td><?=h($fmt($r['best_wtb_ecto']??null))?></td><td><?=h($fmt($r['best_wts_ecto']??null))?></td><td><?=h($fmt($r['median_wts_ecto']??$r['median_wtb_ecto']??null))?></td><td><?=number_format((float)($r['confidence_score']??0),0)?>%</td><td><?=number_format((float)($r['deal_score']??0),0)?></td></tr><?php endforeach;?></tbody></table></div></section>